style.css:
@-moz-document domain("homedepot.com"), domain("www.homedepot.com") {
/* Home Depot Orange Charcoal Glass v1.0.1
   Legacy Mozilla format: one document wrapper, flat rules, no metadata.
   Palette: charcoal #0a0a0a; grid #1a1a1a; orange #f96302.
*/
html {
  color-scheme: dark !important;
  background: #0a0a0a !important;
}
body {
  background-color: #0a0a0a !important;
  background-image: linear-gradient(#1a1a1a 1px, transparent 1px), linear-gradient(90deg, #1a1a1a 1px, transparent 1px), repeating-linear-gradient(0deg, rgba(249,99,2,.025) 0, rgba(249,99,2,.025) 1px, transparent 1px, transparent 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-attachment: fixed !important;
  color: #ffad52 !important;
}
body, body *:not(svg):not(path):not(use):not([class*="icon-font"]):not([class*="IconFont"]):not(.material-icons) {
  font-family: "Cascadia Code", "SFMono-Regular", Consolas, "Liberation Mono", "Courier New", monospace !important;
}
/* Text uses explicit selectors so native icons and product artwork survive. */
body p, body span, body label, body li, body dt, body dd, body td, body th, body legend, body summary,
.sui-text-primary, .sui-text-inverse, .sui-text-inherit, .sui-text-current {
  color: #ffad52 !important;
}
body h1, body h2, body h3, body h4, body h5, body h6,
.sui-text-brand, .sui-text-success, .sui-text-badge-accent-teal-regular {
  color: #ff9500 !important;
}
body small, body figcaption, .sui-text-subtle, .sui-text-inactive, .breadcrumb__item {
  color: #c2a58e !important;
}
body a, body a:visited, body a span, body a p { color: #ff9a1f !important; }
body a:hover, body a:hover span, body a:hover p { color: #ffc16b !important; }
body a:focus-visible, body button:focus-visible, body input:focus-visible, body select:focus-visible, body textarea:focus-visible, [tabindex]:focus-visible {
  outline: 2px solid #ff9c4d !important;
  outline-offset: 3px !important;
}
::selection { background: #f96302 !important; color: #0a0a0a !important; }
/* Keep the grid visible through layout roots. */
#root, #__next, #app, #container, #content, #main, main, .experience, .my-homepage,
.main-content, .mainContent, .content-wrapper, .page-wrapper, .grid, .grid-container,
[data-testid="layout-test"], [data-testid="layout-section"] {
  background-color: transparent !important;
}
/* Current Home Depot SUI surface utilities, plus earlier site layouts. */
.sui-bg-primary, .sui-bg-subtle, .sui-bg-medium, .sui-bg-strong,
.sui-bg-info, .sui-bg-inverse, [class~="sui-bg-primary/60"], [class~="lg:sui-bg-primary"],
.bg-white, .u__bgColor--white, .u__bgColor--f5f5f5, .u__bgColor--f9f9f9,
.u__bgColor--eeeeee, .u__bgColor--f2f2f2,
div[style*="background-color: white"], div[style*="background-color: rgb(255, 255, 255)"],
section[style*="background-color: white"], section[style*="background-color: rgb(255, 255, 255)"] {
  background-color: rgba(24,23,22,.94) !important;
  color: #ffad52 !important;
}
.sui-bg-brand { background-color: #a94000 !important; color: #ffbd70 !important; }
.sui-border-primary, .sui-border-input-primary, .sui-border-accent,
body hr, body fieldset, body table, body th, body td {
  border-color: rgba(249,99,2,.32) !important;
}
/* Main header and footer are readable glass, with no fixed-position changes. */
[data-testid="header-root"], header, .Header, .header, #header,
.header-container, .header-wrapper, #header-container,
#footer-static, footer, .footer, .Footer {
  background-color: rgba(18,18,18,.97) !important;
  color: #ffad52 !important;
  border-color: rgba(249,99,2,.45) !important;
  box-shadow: 0 3px 18px rgba(0,0,0,.35) !important;
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
}
[data-testid="header-thd-logo"] {
  background: transparent !important;
  filter: drop-shadow(0 0 7px rgba(249,99,2,.6)) !important;
}
img[alt="The Home Depot Logo"] {
  background: transparent !important;
  opacity: 1 !important;
}
.sui-fill-primary, .sui-fill-brand, .sui-fill-inverse,
button svg, [role="button"] svg, nav svg, [data-testid="header-cart-icon"] svg {
  fill: #ffad66 !important;
  color: #ff9500 !important;
}
/* Cards: a single outside border avoids cluttered nested outlines. */
[data-testid="product-pod"], [data-testid="recs-product-pod"],
[data-testid="product-pod-container"], .product-pod, .product-pod--default,
.browse-search__pod, .product-card, .product-tile, .card-tile__collection,
.store-workshop-card, .content-card, .rail-card, .cart-item, .cartItem,
.order-summary, .orderSummary, .buybox, .buy-box {
  background-color: rgba(25,24,23,.92) !important;
  color: #ffad52 !important;
  border: 1px solid rgba(249,99,2,.38) !important;
  border-radius: 10px !important;
  box-shadow: 0 4px 14px rgba(0,0,0,.28) !important;
}
[data-testid="product-pod"]:hover, [data-testid="recs-product-pod"]:hover,
.product-pod:hover, .product-card:hover, .product-tile:hover, .card-tile__collection:hover {
  border-color: #f96302 !important;
  box-shadow: 0 0 0 1px rgba(249,99,2,.32), 0 4px 16px rgba(0,0,0,.36) !important;
}
.product-shelf, .product-shelf__carousel--wrapper, .product-shelf__dynamic-aisle {
  background-color: transparent !important;
}
.product-pod__title, .product-title, .product-details, .product-info,
[data-testid="product-header"], [data-testid="product-details"],
[data-testid="product-pod"] .sui-bg-primary,
[data-testid="recs-product-pod"] .sui-bg-primary {
  background-color: transparent !important;
  color: #ffad52 !important;
}
.price, .price-format, .price__dollars, .price__cents, .price__currency,
[data-testid="price"], [data-testid="price-format"], [class*="price-format"] span {
  color: #ff9a1f !important;
}
/* Menus and overlays need a nearly solid base rather than stacked transparency. */
[role="dialog"], dialog, [role="menu"], [role="listbox"],
.sui-drawer, .sui-modal, .sui-popover, .sui-menu,
.drawer, .drawer-content, .modal-content, .overlay-content,
.popover, .dropdown-menu, .typeahead, .typeahead__results,
[data-testid="drawer-content"], [data-testid="modal-content"],
[data-testid="typeahead-results"], [data-testid="search-results"],
.ReactModal__Content, .sui-paper {
  background-color: rgba(23,22,21,.98) !important;
  background-image: none !important;
  color: #ffad52 !important;
  border-color: rgba(249,99,2,.5) !important;
  box-shadow: 0 8px 32px rgba(0,0,0,.65) !important;
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
}
[role="menuitem"], [role="option"] { color: #ff9a1f !important; }
[role="menuitem"]:hover, [role="option"]:hover, [role="option"][aria-selected="true"] {
  background-color: #3b271b !important;
  color: #ffc16b !important;
}
.modal-backdrop, .drawer-backdrop, [data-testid="drawer-backdrop"],
[class~="sui-bg-inverse/50"] { background-color: rgba(0,0,0,.72) !important; }
/* Product filters, accordions, reviews, specifications and cart surfaces. */
aside, .results-filters, .filter-panel, .filter-refinement,
.filter-refinements, .browse-search__filter, .accordion,
.accordion__content, .accordion__header, .specifications,
.specifications__table, .ratings-and-reviews, .review, .review-card,
.cart, .cart-container, .checkout, .checkout-container,
[data-testid="accordion"], [data-testid="accordion-summary"], [data-testid="accordion-details"],
[data-testid="order-summary"], [data-testid="cart-item"], [data-testid="fulfillment"],
.bui-accordion, .bui-accordion__header, .bui-accordion__content {
  background-color: rgba(26,25,24,.94) !important;
  color: #ffad52 !important;
  border-color: rgba(249,99,2,.32) !important;
}
body table { background: #191817 !important; }
body th { background: #302319 !important; color: #ff9a1f !important; }
body tr:nth-child(even) td { background: #211e1b !important; }
/* Inputs and native form controls. Never alter size, display, or click behavior. */
body input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="hidden"]):not([type="submit"]):not([type="button"]),
body textarea, body select, [data-testid="search-field-root"], [data-testid="search-field-container"] {
  background-color: #141414 !important;
  color: #ffb45e !important;
  border-color: #965025 !important;
  caret-color: #ff9c4d !important;
}
body input::placeholder, body textarea::placeholder { color: #b99d86 !important; opacity: 1 !important; }
body option, body optgroup { background: #1b1a19 !important; color: #ffb45e !important; }
body input[type="checkbox"], body input[type="radio"], body input[type="range"], progress { accent-color: #f96302 !important; }
body button, body input[type="submit"], body input[type="button"], .bttn, .button, .btn {
  background-color: #29211b !important;
  background-image: none !important;
  border-color: #a45420 !important;
  color: #ffa329 !important;
}
body button span, body button p, .bttn span, .button span, .btn span {
  color: inherit !important;
}
body button:hover, .bttn:hover, .button:hover, .btn:hover {
  background-color: #49301f !important;
  color: #ffc16b !important;
  border-color: #ff9c4d !important;
}
.bttn--primary, .button--primary, .btn-primary, button.sui-bg-brand, a.sui-bg-brand,
button[data-testid="add-to-cart"], button[data-testid="add-to-cart-button"],
button[data-testid="buy-now"], [data-testid="add-to-cart"] button {
  background: #f96302 !important;
  border-color: #ff9c4d !important;
  color: #16100c !important;
  font-weight: 700 !important;
}
.bttn--primary span, .button--primary span, .btn-primary span, a.sui-bg-brand span,
button.sui-bg-brand span, button[data-testid="add-to-cart"] span,
button[data-testid="add-to-cart-button"] span { color: #16100c !important; }
.bttn--primary:hover, button.sui-bg-brand:hover, a.sui-bg-brand:hover,
button[data-testid="add-to-cart"]:hover, button[data-testid="add-to-cart-button"]:hover {
  background: #ff9c4d !important;
  color: #16100c !important;
}
body button:disabled, body input:disabled, [aria-disabled="true"] { opacity: .5 !important; }
[role="tab"][aria-selected="true"], [aria-current="page"], .pagination__item--active {
  color: #ff9500 !important;
  border-color: #f96302 !important;
  background-color: #302116 !important;
}
/* Photo wrappers lose white surfaces; baked-in image whites stay natural. */
[data-testid="product-image__wrapper"], .product-image, .product-pod__image,
.product-image-wrapper, .mediagallery, .media-gallery, .thumbnail, .thumbnails {
  background-color: #222120 !important;
  border-color: rgba(249,99,2,.25) !important;
}
img, video, canvas, picture, [data-testid="product-image__wrapper"] img,
.product-pod img, .product-card img {
  filter: none !important;
  mix-blend-mode: normal !important;
}
/* No pseudo-element tint overlays are introduced over photos. */
.alert, [role="alert"], .sui-bg-warning, .sui-bg-danger, .sui-bg-success {
  background-color: #35251b !important;
  color: #ffb45e !important;
  border-color: #cf7b3c !important;
}
.sui-text-danger, .sui-text-error, .error, .validation-error { color: #ffaf9c !important; }
body del, body s { color: #b59c88 !important; }
/* Matching native Firefox and Chromium scrollbars. */
* { scrollbar-color: #b85212 #111111 !important; scrollbar-width: thin !important; }
::-webkit-scrollbar { width: 11px !important; height: 11px !important; }
::-webkit-scrollbar-track, ::-webkit-scrollbar-corner { background: #111111 !important; }
::-webkit-scrollbar-thumb { background: #b85212 !important; border: 2px solid #111111 !important; border-radius: 8px !important; }
::-webkit-scrollbar-thumb:hover { background: #f96302 !important; }
}
